with vals(fintech_id,business_model,target_customer,revenue_model,bm_conf,tc_conf,rev_conf,bm_basis,tc_basis,rev_basis,source_url) as (
 values
 ('ENT-RUT-77101928-5','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'SumUp provee POS, Tap to Pay, cuenta digital, links de pago y software de gestión a comercios y emprendimientos.','El cliente económico observable es el comercio/negocio que adquiere o arrienda el equipo y paga las comisiones; el consumidor final sólo actúa como pagador.','SumUp cobra comisiones porcentuales por transacción y, en algunos planes, un valor mensual por equipamiento/servicio.','https://www.sumup.com/es-cl/precios/'),
 ('ENT-RUT-76187287-7','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Khipu conecta comercios y plataformas con pagos cuenta a cuenta, pagos automáticos y APIs de Open Finance.','El producto de pagos requiere una cuenta de cobrador/comercio y sus APIs se integran a negocios, desarrolladores y organizaciones.','Khipu publica para pagos instantáneos una tarifa porcentual de 0,6% + IVA sobre el monto recaudado, con descuentos por volumen.','https://www.khipu.com/page/tarifas-instantaneos-argentina'),
 ('ENT-RUT-59226790-K','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Fintoc es infraestructura de pagos para empresas con checkout, pagos recurrentes, transferencias, cuentas empresa y conexiones bancarias.','La oferta vigente está diseñada para empresas que procesan pagos digitales y necesitan integración API/checkout/recaudación.','Fintoc comercializa pagos destacando una comisión por transacción y reducción de costo frente a tarjetas; se mantiene la clasificación ya observada como comisión transaccional.','https://www.fintoc.com/cl/producto/payments/transferencias'),
 ('ENT-RUT-77224915-2','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'tapi es infraestructura regional de pagos y cobros vía una única API para bancos, fintechs, billeteras y otras empresas.','La compañía se define como aliado tecnológico de empresas y permite que compañías incorporen pagos de servicios, cash in/out, recargas y gift cards a sus productos.','La evidencia pública revisada no expone una tarifa principal suficientemente precisa para asignar un único modelo de monetización.','https://tapi.la/')
), logged as (
 select v.fintech_id,'MANUAL_OFFICIAL_PAYMENTS_INFRA_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,v.revenue_model,v.rev_conf,1,now(),jsonb_build_object('source_url',v.source_url,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'manual_validation',true,'cohort','PAYMENTS_INFRA_III') from vals v returning fintech_id
)
update public.aml_fintech_entity e
set business_model=v.business_model,target_customer=v.target_customer,revenue_model=v.revenue_model,business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=v.rev_basis,revenue_model_confidence=v.rev_conf,profile_classifier_version='MANUAL_OFFICIAL_PAYMENTS_INFRA_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
from vals v where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

on conflict(observation_key) do update set evidence_status=excluded.evidence_status,evidence_class=excluded.evidence_class,confidence=excluded.confidence,basis=excluded.basis,source_code=excluded.source_code,source_url=excluded.source_url,evidence_excerpt=excluded.evidence_excerpt,last_seen_at=now(),observed_at=excluded.observed_at;

on conflict(observation_key) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,qualifier=excluded.qualifier,evidence_type=excluded.evidence_type,confidence=excluded.confidence,source_url=excluded.source_url,observed_at=excluded.observed_at,basis=excluded.basis,evidence_excerpt=excluded.evidence_excerpt,metadata=excluded.metadata,last_seen_at=now();

select public.aml_fintech_refresh_functional_profile();